    local_thread_pool =
        std::make_unique<ailego::ThreadPool>(options.write_concurrency, false);
    reducer->set_thread_pool(local_thread_pool.get());
    effective_write_concurrency =
        static_cast<uint32_t>(local_thread_pool->count());
  }

