87	int VamanaIndex::_prepare_for_search(
88	    const VectorData & /*vector_data*/,
89	    const BaseIndexQueryParam::Pointer &search_param,
90	    core::IndexContext::Pointer &context) {
91	  const auto &vamana_search_param =
92	      std::dynamic_pointer_cast<VamanaQueryParam>(search_param);
93	
94	  if (ailego_unlikely(!vamana_search_param)) {
95	    LOG_ERROR("Invalid search param type, expected VamanaQueryParam");
96	    return core::IndexError_Runtime;
97	  }
98	
99	  if (search_param->group_by_param && search_param->group_by_param->group_by) {
100	    LOG_ERROR("group_by search is not supported for Vamana index");
101	    return core::IndexError_Unsupported;
102	  }
103	
104	  if (vamana_search_param->ef_search == 0 ||
105	      vamana_search_param->ef_search > 2048) {
106	    LOG_ERROR(
107	        "ef_search must be greater than 0 and less than or equal to 2048.");
108	    return core::IndexError_Runtime;
109	  }
110	
111	  context->set_topk(vamana_search_param->topk);
112	  context->set_fetch_vector(vamana_search_param->fetch_vector);
113	  if (vamana_search_param->filter && vamana_search_param->filter->is_valid()) {
114	    context->set_filter(std::move(*vamana_search_param->filter));
115	  } else {
116	    context->reset_filter();
117	  }
118	  if (vamana_search_param->radius > 0.0f) {
119	    context->set_threshold(vamana_search_param->radius);
120	  }
121	  ailego::Params params;
122	  const uint32_t real_search_ef =
123	      std::max(1u, std::min(2048u, vamana_search_param->ef_search));
124	  params.set(core::PARAM_VAMANA_STREAMER_EF, real_search_ef);
125	  const uint32_t real_search_po =
126	      std::min(256u, vamana_search_param->prefetch_offset);
127	  params.set(core::PARAM_VAMANA_STREAMER_PO, real_search_po);
128	  const uint32_t real_search_pl =
129	      std::min(256u, vamana_search_param->prefetch_lines);
130	  params.set(core::PARAM_VAMANA_STREAMER_PL, real_search_pl);
131	  context->update(params);
132	  return 0;
133	}
