    if (ret != 0) return ret;
    if (converter_) {
      ret = converter_->dump(dumper);
      if (ret != 0) return ret;
    }
    ret = dumper->close();
    if (ret != 0) return ret;
    dumper.reset();
    ret = reset_builder();
    if (ret != 0) return ret;
    build_stage_ = BuildStage::kDumped;
  } else if (build_stage_ != BuildStage::kDumped) {
    return core::IndexError_NoReady;
  }
  AILEGO_DEFER([&]() {
    if (!is_trained_) {
      if (streamer_) streamer_->close();
