  if (reformer_) {
    ret = reformer_->load(storage_);
    if (ret != 0) return ret;
  }
  is_trained_ = true;
  converter_.reset();
  holder_.reset();
  decltype(doc_cache_)().swap(doc_cache_);
  return 0;
}

