711	  AILEGO_DEFER([&]() { holder->set_stop_flag(nullptr); });
712	  IndexHolder::Pointer target_holder = holder;
713	  // IVF and DiskAnn propagate source read failures during dump.
714	  // Other builders retain an owned multipass snapshot, as before, so their
715	  // dump paths never depend on a source provider or its deferred error state.
716	  if (target_builder_->name() != "IVFBuilder" &&
717	      target_builder_->name() != "DiskAnnBuilder") {
718	    switch (holder->data_type()) {
