378	int DiskAnnBuilder::train_quantized_data(IndexThreads::Pointer threads) {
379	  LOG_INFO("Starting Train: Chunk Num: %u", pq_chunk_num_);
380	
381	  ailego::ElapsedTime timer;
382	
383	  quantizer_ = IndexFactory::CreateQuantizer("PqInt8Quantizer");
384	  if (!quantizer_) {
385	    LOG_ERROR("Create PqInt8Quantizer failed");
386	    return IndexError_NoExist;
387	  }
388	
389	  ailego::Params qp;
390	  qp.set("num_chunk", pq_chunk_num_);
391	  // The quantizer creates its own pool, so bound it by the caller's pool.
392	  const auto pq_thread_count = static_cast<uint32_t>(std::max<size_t>(
393	      1, std::min<size_t>(build_thread_count_, threads->count())));
394	  qp.set("thread_count", pq_thread_count);
395	  qp.set("use_zero_mean", false);
396	  int ret = quantizer_->init(build_meta_, qp);
397	  if (ret != 0) {
398	    LOG_ERROR("PqInt8Quantizer init failed, ret=%d", ret);
399	    return ret;
400	  }
401	
402	  // Keep the legacy prefix and sample order without materializing a second
403	  // training holder. The quantizer copies only its selected training rows.
404	  IndexHolder::Pointer training_holder = std::make_shared<PrefixIndexHolder>(
405	      holder_, max_train_sample_count_, build_meta_);
406	  ret = quantizer_->train(std::move(training_holder));
407	  if (ret != 0) {
408	    LOG_ERROR("PqInt8Quantizer train failed, ret=%d", ret);
409	    return ret;
410	  }
411	
412	  std::string &quantizer_meta_buffer = entity_.pq_quantizer_meta_buffer();
413	  ret = quantizer_->serialize(&quantizer_meta_buffer);
414	  if (ret != 0) {
415	    LOG_ERROR("PqInt8Quantizer serialize failed, ret=%d", ret);
416	    return ret;
417	  }
418	
419	  size_t pq_time = timer.milli_seconds();
420	  LOG_INFO("Train Quantized Data Done, time: %zu ms", pq_time);
421	
422	  (*entity_.mutable_pq_meta()).quantizer_meta_buffer_size =
423	      quantizer_meta_buffer.size();
424	  (*entity_.mutable_pq_meta()).chunk_num = pq_chunk_num_;
425	
426	  return 0;
427	}
